#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
GH_REPO="${GH_REPO:-}" # owner/repo for gh writes; empty = infer from cwd
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# _gh_ready — gh installed and authenticated?
_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# preflight_gh — prove gh can actually reach the repo BEFORE any stage asks for
# a credential. A token that cannot resolve the repo must fail here, not after
# the human has minted a password. Call once, right after banner.
preflight_gh() {
  local out="" rc=0
  if ! command -v gh >/dev/null 2>&1; then
    warn "gh not installed — secrets will be skipped"; return 1
  fi
  if ! gh auth status >/dev/null 2>&1; then
    warn "gh not authenticated — run: gh auth login"; return 1
  fi
  if [[ -n "$GH_REPO" ]]; then
    out=$(gh repo view "$GH_REPO" --json nameWithOwner 2>&1 >/dev/null) || rc=$?
  else
    out=$(gh repo view --json nameWithOwner 2>&1 >/dev/null) || rc=$?
  fi
  (( rc == 0 )) && return 0
  warn "gh cannot reach ${GH_REPO:-the current repo}: ${out%%$'\n'*}"
  note "fix the token scope now, or every secret below will be skipped"
  return 1
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh, targeting
# $GH_REPO when set. Reports gh's own error rather than hiding it: a silent
# "skipped" reads as done and is how a wizard finishes with nothing written.
set_secret() {
  local name="$1" value="$2" err="" rc=0
  if ! _gh_ready; then
    err="gh not installed or not authenticated"; rc=1
  elif [[ -n "$GH_REPO" ]]; then
    err=$(printf '%s' "$value" | gh secret set "$name" --repo "$GH_REPO" 2>&1 >/dev/null) || rc=$?
  else
    err=$(printf '%s' "$value" | gh secret set "$name" 2>&1 >/dev/null) || rc=$?
  fi
  if (( rc == 0 )); then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  err="${err%%$'\n'*}"; [[ -n "$err" ]] || err="gh exited $rc"
  SKIPPED+=("GitHub secret $name — $err")
  warn "skipped GitHub secret $name: $err"
  return 0
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2" err="" rc=0
  if ! _gh_ready; then
    err="gh not installed or not authenticated"; rc=1
  elif [[ -n "$GH_REPO" ]]; then
    err=$(gh variable set "$name" --repo "$GH_REPO" --body "$value" 2>&1 >/dev/null) || rc=$?
  else
    err=$(gh variable set "$name" --body "$value" 2>&1 >/dev/null) || rc=$?
  fi
  if (( rc == 0 )); then
    printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  err="${err%%$'\n'*}"; [[ -n "$err" ]] || err="gh exited $rc"
  SKIPPED+=("GitHub variable $name — $err")
  warn "skipped GitHub variable $name: $err"
  return 0
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set the two totals to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Braces + exit: bash parses the whole block before running it, so saving an
# edit to this file mid-run can't make bash resume at a stale byte offset.
{
TOTAL_STAGES=6
TOTAL_MINUTES=125

GH_REPO="bcn-services/bcns-client-technology-associates"
REPO_DIR="$HOME/bcns-client-technology-associates"
ENV_FILE="$HOME/.ta-sync-wizard-no-env" # nothing here goes to a local .env; also stops ask() offering .env values
KEYCHAIN_SERVICE="bcns-ta-sync-github-token"
WF="sync-legacy.yml"

# pat_status TOKEN — HTTP status of reading the sync workflow with TOKEN (header via stdin, never argv)
pat_status() {
  printf 'header = "Authorization: Bearer %s"\n' "$1" |
    curl -sS -K - -o /dev/null -w '%{http_code}' \
      "https://api.github.com/repos/$GH_REPO/actions/workflows/$WF"
}

# watch_latest_run — watch the newest sync-legacy run; success iff it concludes green
watch_latest_run() {
  local id
  sleep 5
  id=$(gh run list -R "$GH_REPO" -w "$WF" -L 1 --json databaseId -q '.[0].databaseId')
  [[ -n "$id" ]] || { warn "no $WF run found"; return 1; }
  note "https://github.com/$GH_REPO/actions/runs/$id"
  gh run watch "$id" -R "$GH_REPO" --exit-status
}

banner "TA — Sync from Access go-live"
preflight_gh

# FROM_STAGE=4 <wizard> resumes at stage 4 (1-3 done 2026-10-21; re-running 2 would mint a second token).
if (( ${FROM_STAGE:-1} <= 3 )); then
# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight — PR #41 merged and deployed" 1
say "The sync page, sync_runs table (0014) and $WF must be on prod before anything else."
pr_state=$(gh pr view 41 -R "$GH_REPO" --json state -q .state 2>/dev/null || echo unknown)
note "PR #41: $pr_state"
if [[ "$pr_state" != "MERGED" ]]; then
  warn "PR #41 is not merged. Merge it (deploy.yml applies 0014), wait for deploy to go green, then re-run."
  exit 1
fi
gh run list -R "$GH_REPO" -w deploy.yml -L 1 --json conclusion,headSha -q '.[0] | "last deploy: \(.conclusion) @ \(.headSha[0:7])"' 2>/dev/null | while read -r l; do note "$l"; done
confirm "Is that last deploy green and at (or after) the PR #41 merge?" || { warn "Wait for deploy.yml, then re-run."; exit 1; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub — mint GITHUB_SYNC_TOKEN" 6
say "A fine-grained token the app uses to dispatch $WF. Nothing else."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: ta-sync-dispatch   ·   Resource owner: bcn-services"
step "Expiration: the longest allowed (custom, 1 year if 'no expiration' is blocked)."
step "Repository access: Only select repositories → bcns-client-technology-associates"
step "Repository permissions → Actions: Read and write (Metadata: Read is added automatically)."
step "Generate token, then copy it."
note "If bcn-services requires approval, approve it at github.com/organizations/bcn-services/settings/personal-access-token-requests."
ask_secret GITHUB_SYNC_TOKEN "Paste the token:"
[[ -n "$GITHUB_SYNC_TOKEN" ]] || { warn "No token entered."; exit 1; }
code=$(pat_status "$GITHUB_SYNC_TOKEN")
if [[ "$code" != "200" ]]; then
  warn "Token can't read $WF (HTTP $code). Pending org approval, wrong repo, or missing Actions permission."
  exit 1
fi
note "token reads the workflow (HTTP 200)"
security add-generic-password -U -a "$USER" -s "$KEYCHAIN_SERVICE" -l "TA sync GITHUB_SYNC_TOKEN" -w "$GITHUB_SYNC_TOKEN"
note "backed up to keychain: $KEYCHAIN_SERVICE"
note "re-read later: security find-generic-password -s $KEYCHAIN_SERVICE -w"
warn "Put the expiry date in your calendar: once it lapses, every Sync click fails at dispatch."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Droplet — set GITHUB_SYNC_TOKEN in /srv/ta/env" 3
say "Writes the token into /srv/ta/env over ssh (stdin, never argv), restarts bcns-app@ta, checks the pid changed."
ask DROPLET_HOST "Droplet IP or ssh host (same as the DEPLOY_HOST secret):"
[[ -n "$DROPLET_HOST" ]] || { warn "No host entered."; exit 1; }
# shellcheck disable=SC2016 # expanded on the droplet
if ssh -i "$HOME/.ssh/id_ed25519_bcns" -o BatchMode=yes "root@$DROPLET_HOST" 'set -eu
  read -r tok
  f=/srv/ta/env
  old=$(systemctl show -p MainPID --value bcns-app@ta)
  tmp=$(mktemp "$f.XXXXXX")
  grep -v "^GITHUB_SYNC_TOKEN=" "$f" > "$tmp" || true
  printf "GITHUB_SYNC_TOKEN=%s\n" "$tok" >> "$tmp"
  chown --reference="$f" "$tmp"; chmod --reference="$f" "$tmp"
  mv "$tmp" "$f"
  systemctl restart bcns-app@ta
  sleep 4
  new=$(systemctl show -p MainPID --value bcns-app@ta)
  systemctl is-active --quiet bcns-app@ta
  echo "bcns-app@ta pid $old -> $new"
  [ "$new" != "$old" ] && [ "$new" != 0 ]' <<<"$GITHUB_SYNC_TOKEN"; then
  note "droplet updated, app restarted on a new pid"
else
  warn "Droplet step failed (see above). /srv/ta/env is either untouched or fully replaced, never half-written."
  SKIPPED+=("GITHUB_SYNC_TOKEN on the droplet: set /srv/ta/env, systemctl restart bcns-app@ta")
fi
say "Check: https://ta.bcn-services.com/sync as an admin — the Sync button should now be enabled."
pause

else
  _STAGE_INDEX=3; _MINUTES_ELAPSED=10
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "S3 — read-only backup key + rehearsal run" 45
say "Needs Kris's read-only key for the nightly backup bucket. The rehearsal loads into a throwaway"
say "stack on the runner, never prod: it proves download, restore, scripter and verify end to end."
if confirm "Has Kris supplied the read-only key?"; then
  ask S3_BUCKET "Bucket name [techassoc-tranfer]:"
  S3_BUCKET="${S3_BUCKET:-techassoc-tranfer}"
  ask S3_ENDPOINT "S3 endpoint URL (empty if it is real AWS):"
  ask AWS_DEFAULT_REGION "Region [us-east-1]:"
  AWS_DEFAULT_REGION="${AWS_DEFAULT_REGION:-us-east-1}"
  ask_secret AWS_ACCESS_KEY_ID "Access key id:"
  ask_secret AWS_SECRET_ACCESS_KEY "Secret access key:"

  step "Listing the bucket with this key..."
  if newest=$(AWS_ACCESS_KEY_ID="$AWS_ACCESS_KEY_ID" AWS_SECRET_ACCESS_KEY="$AWS_SECRET_ACCESS_KEY" \
      AWS_DEFAULT_REGION="$AWS_DEFAULT_REGION" aws s3api list-objects-v2 --bucket "$S3_BUCKET" \
      --prefix DB_Backup/TECH05/SQLBackupRestore/DailyBackups/ \
      ${S3_ENDPOINT:+--endpoint-url "$S3_ENDPOINT"} \
      --query 'sort_by(Contents,&LastModified)[-1].[Key,LastModified]' --output text); then
    note "newest object: $newest"
    warn "If that timestamp is more than ~96h old the sync will refuse it (MAX_BACKUP_AGE_HOURS). Ask Kris if the nightly job runs."
  else
    warn "Listing failed. Check endpoint/region/key with Kris before setting secrets."
    confirm "Set the secrets anyway?" || exit 1
  fi

  set_secret S3_BUCKET "$S3_BUCKET"
  [[ -n "$S3_ENDPOINT" ]] && set_secret S3_ENDPOINT "$S3_ENDPOINT"
  set_secret AWS_DEFAULT_REGION "$AWS_DEFAULT_REGION"
  set_secret AWS_ACCESS_KEY_ID "$AWS_ACCESS_KEY_ID"
  set_secret AWS_SECRET_ACCESS_KEY "$AWS_SECRET_ACCESS_KEY"

  if confirm "Dispatch the rehearsal now (rehearsal=true, never touches prod)?"; then
    gh workflow run "$WF" -R "$GH_REPO" -f rehearsal=true
    if watch_latest_run; then note "rehearsal passed"; else
      warn "Rehearsal failed. Do NOT run a prod sync; send the run link back to a Claude window."
      exit 1
    fi
  else
    SKIPPED+=("rehearsal: gh workflow run $WF -R $GH_REPO -f rehearsal=true")
  fi
else
  SKIPPED+=("S3 secrets + rehearsal: re-run this wizard once Kris sends the read-only key")
  warn "Stopping here: no prod sync without a green rehearsal."
  finish
  exit
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Prod — on-demand pg_dump before the first sync" 10
say "Full custom-format dump of prod, so the sync is reversible. Uses Docker pg_dump matching the server"
say "(local pg_dump 14 is too old). Reads DATABASE_URL from .env.local; never printed."
docker info >/dev/null 2>&1 || { warn "Docker is not running: colima start --memory 6, then re-run."; exit 1; }
mkdir -p "$HOME/Backups"
DUMP="ta-prod-pre-sync-$(date +%Y%m%dT%H%M).dump"
if (
  set -eu
  PGURL=$(grep '^DATABASE_URL=' "$REPO_DIR/.env.local" | cut -d= -f2- | sed 's/:6543/:5432/')
  [ -n "$PGURL" ] || { echo "no DATABASE_URL in .env.local" >&2; exit 1; }
  export PGURL
  ver=$(docker run --rm -e PGURL postgres:17 sh -c 'psql -X -At -d "$PGURL" -c "show server_version_num"')
  major=$((ver / 10000))
  echo "  server major $major"
  docker run --rm -e PGURL -v "$HOME/Backups:/out" "postgres:$major" \
    sh -c "pg_dump -Fc -d \"\$PGURL\" -f /out/$DUMP"
) && [[ -s "$HOME/Backups/$DUMP" ]]; then
  note "dump: ~/Backups/$DUMP ($(du -h "$HOME/Backups/$DUMP" | cut -f1))"
  note "restore if needed: pg_restore --clean --if-exists --data-only -t <table> ..."
else
  warn "pg_dump failed. Do NOT sync without a dump."
  exit 1
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Prod — first sync, with you watching" 60
say "This overwrites the 20 legacy tables from the newest backup. Kept: users, bank imports, audit log,"
say "tickets, sync history. Lost: anything typed into cases/clients/bills/time/expenses/funds since that backup."
warn "Tell Kris and Kalpna: nobody enters data for the next hour."
if confirm "Ready to run the first prod sync now?"; then
  open_url "https://ta.bcn-services.com/sync"
  step "Sign in as an admin, click Sync, accept the confirm."
  pause "Press Enter once you've clicked Sync"
  if watch_latest_run; then
    note "sync succeeded — the page should show Succeeded with the backup timestamp"
  else
    warn "Sync failed. The load is one transaction: on a load failure nothing changed."
    warn "If the error says verify failed, the data DID load: restore from ~/Backups/$DUMP before anyone works."
  fi
else
  SKIPPED+=("first prod sync: click Sync at https://ta.bcn-services.com/sync, then gh run watch")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
exit
}
